def test_class_collect_branches_and_warnings(pytester):
    # Create a test module with three classes:
    # 1. A class with an __init__ method (should be skipped with a warning).
    # 2. A class with a __new__ method (should be skipped with a warning).
    # 3. A normal test class with a test method (should be collected and pass).
    # 4. A class with __test__ = False (should be ignored without warning).
    pytester.makepyfile(
        test_mod="""
            import pytest

            class WithInit:
                def __init__(self):
                    pass

                def test_method(self):
                    assert False  # should never be run

            class WithNew:
                def __new__(cls):
                    return super().__new__(cls)

                def test_method(self):
                    assert False  # should never be run

            class Normal:
                def test_method(self):
                    assert True

            class Ignored:
                __test__ = False

                def test_method(self):
                    assert False  # should never be run, class is ignored
        """
    )
    # Run pytest with verbose output to capture collection warnings.
    result = pytester.runpytest("-vv")
    # The normal test should pass.
    result.stdout.fnmatch_lines("*1 passed*")
    # The classes with __init__ and __new__ should emit collection warnings.
    result.stdout.fnmatch_lines("*cannot collect test class*WithInit*__init__*")
    result.stdout.fnmatch_lines("*cannot collect test class*WithNew*__new__*")
    # The ignored class should not produce any warning or test.
    # Ensure no unexpected failures or errors.
    result.stdout.no_fnmatch_line("*ERROR*")
