from _pytest.python import hasinit


def test_hasinit_detects_custom_init_on_class():
    class Custom:
        def __init__(self, x):
            self.x = x

    assert hasinit(Custom) is True
    # also true for an instance of the class
    assert hasinit(Custom()) is True


def test_hasinit_returns_false_when_no_init_defined():
    class NoInit:
        pass

    assert hasinit(NoInit) is False
    assert hasinit(NoInit()) is False


def test_hasinit_returns_false_when_inherits_object_init():
    class InheritObject(object):
        pass

    assert hasinit(InheritObject) is False
    assert hasinit(InheritObject()) is False


def test_hasinit_false_for_builtin_types():
    # builtins like int, list, etc., should not have a custom __init__
    for builtin in (int, list, dict, tuple, set, bytes, str, complex, float):
        assert hasinit(builtin) is False
        # Instances of builtins also should return False
        instance = builtin()
        assert hasinit(instance) is False


def test_hasinit_with_function_object_as_init():
    # Manually assign a function to __init__ attribute of a class
    def dummy_init(self):
        pass

    class Dummy:
        pass

    Dummy.__init__ = dummy_init
    # Now __init__ is a plain function, not object.__init__
    assert hasinit(Dummy) is True
    assert hasinit(Dummy()) is True


def test_hasinit_edge_case_none_init():
    class NoneInit:
        __init__ = None

    # __init__ exists but is None, should be considered as not a custom init
    assert hasinit(NoneInit) is False
    assert hasinit(NoneInit()) is False
