from django.core.checks import Error
from django.db import models
from django.test import SimpleTestCase, isolate_apps, override_system_checks


@isolate_apps('check_framework', attr_name='apps')
@override_system_checks([models.checks.model_checks.check_all_models])
class ModelCheckLocalFieldsTests(SimpleTestCase):
    """Tests for Model._check_local_fields error handling."""

    def test_nonexistent_field(self):
        """Referencing a field that does not exist should raise E012."""
        class MyModel(models.Model):
            name = models.CharField(max_length=10)

        errors = MyModel._check_local_fields(['does_not_exist'], 'test_option')
        self.assertEqual(len(errors), 1)
        self.assertIsInstance(errors[0], Error)
        self.assertEqual(errors[0].id, 'models.E012')
        self.assertIn("'test_option' refers to the nonexistent field 'does_not_exist'.", errors[0].msg)

    def test_many_to_many_field(self):
        """Referencing a ManyToManyField should raise E013."""
        class Other(models.Model):
            pass

        class MyModel(models.Model):
            m2m = models.ManyToManyField(Other)

        errors = MyModel._check_local_fields(['m2m'], 'test_option')
        self.assertEqual(len(errors), 1)
        self.assertIsInstance(errors[0], Error)
        self.assertEqual(errors[0].id, 'models.E013')
        self.assertIn(
            "'test_option' refers to a ManyToManyField 'm2m', but ManyToManyFields are not permitted",
            errors[0].msg,
        )

    def test_non_local_field_from_parent(self):
        """Referencing a field defined on a parent (non‑local) should raise E016."""
        class Base(models.Model):
            base_field = models.CharField(max_length=5)

            class Meta:
                abstract = True

        class Child(Base):
            child_field = models.IntegerField()

        # 'base_field' is inherited, not a local field of Child.
        errors = Child._check_local_fields(['base_field'], 'test_option')
        self.assertEqual(len(errors), 1)
        self.assertIsInstance(errors[0], Error)
        self.assertEqual(errors[0].id, 'models.E016')
        self.assertIn(
            "'test_option' refers to field 'base_field' which is not local to model 'Child'.",
            errors[0].msg,
        )

    def test_attname_resolution_for_fk(self):
        """Providing the attname of a ForeignKey should be accepted as a local field."""
        class Target(models.Model):
            pass

        class MyModel(models.Model):
            fk = models.ForeignKey(Target, on_delete=models.CASCADE)

        # The attname for the FK is 'fk_id'.
        errors = MyModel._check_local_fields(['fk_id'], 'test_option')
        self.assertEqual(errors, [])  # No errors expected.

    def test_multiple_errors_combined(self):
        """Mixing several error conditions should return all corresponding errors."""
        class Other(models.Model):
            pass

        class Base(models.Model):
            base = models.CharField(max_length=5)

            class Meta:
                abstract = True

        class MyModel(Base):
            m2m = models.ManyToManyField(Other)
            fk = models.ForeignKey(Other, on_delete=models.CASCADE)

        # 'nonexistent', 'm2m' (M2M), 'base' (non‑local), and a valid attname 'fk_id'.
        errors = MyModel._check_local_fields(
            ['nonexistent', 'm2m', 'base', 'fk_id'],
            'test_option'
        )
        # Expect three errors (E012, E013, E016); 'fk_id' is valid.
        self.assertEqual(len(errors), 3)
        ids = {e.id for e in errors}
        self.assertEqual(ids, {'models.E012', 'models.E013', 'models.E016'})
