    left = {"a": "not-a-list"}
    right = {"x": [1]}

    with pytest.raises(TypeError) as excinfo:
        merge_family(left, right)

    # The exception should contain the type of the offending value
    assert excinfo.value.args[0] is str  # type('not-a-list') == str


