def test_last_item_various_cases():
    # Empty array should return empty list without calling __getitem__
    empty = np.array([]).reshape(0, 3)  # shape with zero size
    assert formatting.last_item(empty) == []

    # Single-element array returns a list with that element
    single = np.array([42])
    assert formatting.last_item(single) == [42]

    # Multi-dimensional array returns the last element as a list
    multi = np.arange(24).reshape(2, 3, 4)  # last element is 23
    assert formatting.last_item(multi) == [23]

    # Custom array-like object to verify the indexer used
    class DummyArray:
        def __init__(self, data):
            self._data = np.asarray(data)

        @property
        def size(self):
            return self._data.size

        @property
        def ndim(self):
            return self._data.ndim

        @property
        def shape(self):
            return self._data.shape

        def __getitem__(self, idx):
            # capture the indexer for inspection
            self.last_indexer = idx
            return self._data[idx]

    dummy = DummyArray(np.arange(8).reshape(2, 2, 2))  # last element is 7
    result = formatting.last_item(dummy)
    # Expected indexer: a tuple of slice(-1, None) repeated ndim times
    expected_indexer = (slice(-1, None),) * dummy.ndim
    assert result == [7]
    assert getattr(dummy, "last_indexer", None) == expected_indexer

    # Verify that for a zero-size custom array, __getitem__ is not invoked
    class ZeroDummy:
        def __init__(self):
            self.called = False

        @property
        def size(self):
            return 0

        @property
        def ndim(self):
            return 2

        @property
        def shape(self):
            return (0, 5)

        def __getitem__(self, idx):
            self.called = True
            return np.array([])

    zero_dummy = ZeroDummy()
    assert formatting.last_item(zero_dummy) == []
    assert not getattr(zero_dummy, "called", False)
