class DummyConfig:
    def __init__(self):
        self.hook = DummyHook()
        self.option = types.SimpleNamespace()
        self._do_configure_called = False

    def _do_configure(self):
        self._do_configure_called = True

    def _ensure_unconfigure(self):
        self.unconfigure_called = True

    # The following are accessed by Session but are not used in our tests
    @property
    def rootdir(self):
        return DummyPath()

    @property
    def invocation_dir(self):
        return DummyPath()

    @property
    def trace(self):
        class DummyTrace:
            def __init__(self):
                self.root = self

            def __call__(self, *args, **kwargs):
                pass

            def __getattr__(self, name):
                # return a dummy callable for any trace method
                return lambda *a, **k: None

            @property
            def indent(self):
                return 0

            @indent.setter
            def indent(self, value):
                pass

        return DummyTrace()

    def getini(self, name):
        # Only needed for norecursedirs default; return empty list
        return []

    def getoption(self, name, default=None):
        return default

    def getvalue(self, name, default=None):
        return default

    def notify_exception(self, excinfo, option):
        selfified = excinfo


# Helper to run wrap_session and capture the returned status and session object
def run_wrap(doit):
    cfg = DummyConfig()
    status = wrap_session(cfg, doit)
    return status, cfg, cfg.hook


def test_wrap_session_normal_flow():
    def doit(config, session):
        # simulate normal execution returning a non-zero exitcode
        return ExitCode.TESTS_FAILED

    status, cfg, hook = run_wrap(doit)
    assert status == ExitCode.TESTS_FAILED
    # ensure session start/finish hooks were called
    assert hook.called.get("sessionstart") is True
    assert isinstance(hook.called.get("sessionfinish"), tuple)
    sess, exitstatus = hook.called["sessionfinish"]
    assert exitstatus == ExitCode.TESTS_FAILED
    # config should have been configured and unconfigured
    assert cfg._do_configure_called is True
    assert getattr(cfg, "unconfigure_called", False) is True


def test_wrap_session_usage_error():
    class MyUsageError(Interrupted):
        pass

    def doit(config, session):
        raise pytest.UsageError("bad usage")

    cfg = DummyConfig()
    with pytest.raises(pytest.UsageError):
        wrap_session(cfg, doit)
    # after raising, exitstatus should be set to USAGE_ERROR
    # Since we cannot get the session directly, we rely on config hook side‑effects
    # The hook's sessionfinish should have been called with USAGE_ERROR
    assert cfg.hook.called["sessionfinish"][1] == ExitCode.USAGE_ERROR
    assert cfg._do_configure_called is True
    assert getattr(cfg, "unconfigure_called", False) is True


def test_wrap_session_failed_exception():
    def doit(config, session):
        raise Failed("failed")

