        raise KeyboardInterrupt

    status, cfg, hook = run_wrap(doit)
    assert status == ExitCode.INTERRUPTED
    # keyboard_interrupt hook should have been called
    assert "keyboard_interrupt" in hook.called
    # sessionfinish should receive INTERRUPTED
    assert hook.called["sessionfinish"][1] == ExitCode.INTERRUPTED


